input.command:
mkdir -p scratch/kraken && cat > scratch/kraken/run.ts <<'EOF'
import * as THREE from "three";
import build from "../../samples/kraken";
const root = build();
const box = new THREE.Box3().setFromObject(root, true);
let meshes = 0, tris = 0, joints = 0;
root.traverse((o: any) => { if (o.isMesh) { meshes++; const g = o.geometry; tris += (g.index ? g.index.count : g.attributes.position.count) / 3; } if (o.isBone || o.userData?.joint) joints++; });
console.log("meshes", meshes, "tris", Math.round(tris), "box", box.min.toArray().map(v=>v.toFixed(2)), box.max.toArray().map(v=>v.toFixed(2)));
console.log("rig chains", (root.userData.rig?.chains ?? []).length, "joints", (root.userData.rig?.joints ?? []).length);
EOF
bun run scratch/kraken/run.ts 2>&1 | tail -30
